ALTER TABLE "production_gate_checks" DROP CONSTRAINT "production_gate_checks_role_chk";--> statement-breakpoint
ALTER TABLE "production_release_signatures" DROP CONSTRAINT "production_release_signatures_role_chk";--> statement-breakpoint
ALTER TABLE "production_gate_checks" ADD CONSTRAINT "production_gate_checks_role_chk" CHECK ("production_gate_checks"."owner_role" IN ('owner','security','operations','product','project-owner') AND jsonb_typeof("production_gate_checks"."evidence_refs")='array' AND jsonb_array_length("production_gate_checks"."evidence_refs") > 0 AND char_length(btrim("production_gate_checks"."checked_by")) BETWEEN 1 AND 200 AND "production_gate_checks"."updated_at" >= "production_gate_checks"."created_at");--> statement-breakpoint
ALTER TABLE "production_release_signatures" ADD CONSTRAINT "production_release_signatures_role_chk" CHECK ("production_release_signatures"."role" IN ('owner','security','operations','product','project-owner') AND "production_release_signatures"."decision"='approved' AND "production_release_signatures"."authentication_method"='oidc');